from abc import ABC, abstractmethod

# Step 2-3: Define the abstract class MediaFile
class MediaFile(ABC):
    def __init__(self, filename):
        self.filename = filename

    @abstractmethod
    def display_info(self):
        pass

# Step 4-5: Define the concrete class VideoFile
class VideoFile(MediaFile):
    def display_info(self):
        print(f"Video File: {self.filename} - Playing...")

# Step 6: Instantiate and call method
video = VideoFile('movie.mp4')
video.display_info()

